2802:     pub fn observe_task(&self, request: &TaskObserveRequest) -> RuntimeResult<TaskObservation> {
2803:         validate_observe_request(request)?;
2804:         let deadline = Instant::now() + Duration::from_millis(request.wait_ms);
2805:         let mut poll_index = 0;
2806:         let mut initial_signature = None;
2807:         loop {
2808:             self.reconcile_job(&request.job_id)?;
2809:             let snapshot = self.registry.job_snapshot(&request.job_id)?;
2810:             let signature =
2811:                 task_activity_signature(snapshot.attempt.as_ref(), &snapshot.projection)?;
2812:             let changed = initial_signature
2813:                 .as_ref()
2814:                 .is_some_and(|initial| initial != &signature);
2815:             if initial_signature.is_none() {
2816:                 initial_signature = Some(signature);
2817:             }
2818:             if snapshot.projection.result_available
2819:                 || request.wait_ms == 0
2820:                 || Instant::now() >= deadline
2821:                 || (request.wait_until == TaskObserveWaitUntil::ChangeOrTerminal && changed)
2822:             {
2823:                 return self.observation_from_snapshot(snapshot, request);
2824:             }
2825:             sleep_until_poll(deadline, &mut poll_index);
2826:         }
2827:     }
