233: fn validate_windows_runtime_context(
234:     snapshot: &WindowsRuntimeContextSnapshot,
235:     authority: WindowsAuthority,
236: ) -> RuntimeResult<()> {
237:     let token_authority_valid = match authority {
238:         WindowsAuthority::Limited => {
239:             !snapshot.token_is_elevated
240:                 && snapshot.token_integrity_level_rid <= 8192
241:                 && (snapshot.administrators_group_attributes == u32::MAX
242:                     || (snapshot.administrators_group_attributes & 0x4) == 0
243:                     || (snapshot.administrators_group_attributes & 0x10) != 0)
244:                 && matches!(
245:                     snapshot.token_selection.as_str(),
246:                     "lua_medium_filtered" | "current_limited"
247:                 )
248:                 && (snapshot.token_selection != "lua_medium_filtered"
249:                     || snapshot.administrators_group_attributes == u32::MAX
250:                     || (snapshot.administrators_group_attributes & 0x10) != 0)
251:         }
252:         WindowsAuthority::Elevated => {
253:             snapshot.token_is_elevated
254:                 && snapshot.token_integrity_level_rid >= 12288
255:                 && snapshot.administrators_group_attributes != u32::MAX
256:                 && (snapshot.administrators_group_attributes & 0x4) != 0
257:                 && (snapshot.administrators_group_attributes & 0x10) == 0
258:                 && snapshot.token_selection == "current_elevated"
259:         }
260:     };
261:     if snapshot.schema_version != 1
262:         || snapshot.token_user_sid.is_empty()
263:         || snapshot.token_type != 1
264:         || !token_authority_valid
265:     {
266:         return Err(RuntimeError::new(
267:             RuntimeErrorCode::InvalidRequest,
268:             format!(
269:                 "Windows runtime context did not prove requested {} authority",
270:                 authority.as_str()
271:             ),
272:             Some("windows.runtimeContext"),
273:             false,
274:         ));
275:     }
276:     for name in REQUIRED_WINDOWS_BASELINE_ENVIRONMENT_NAMES {
277:         if !snapshot
278:             .environment
279:             .iter()
280:             .any(|(actual, value)| actual.eq_ignore_ascii_case(name) && !value.is_empty())
281:         {
282:             return Err(RuntimeError::new(
283:                 RuntimeErrorCode::InvalidRequest,
284:                 format!("Windows runtime context omitted required baseline variable {name}"),
285:                 Some("windows.runtimeContext.environment"),
286:                 false,
287:             ));
288:         }
289:     }
290:     for name in snapshot.environment.keys() {
291:         if !WINDOWS_BASELINE_ENVIRONMENT_NAMES
292:             .iter()
293:             .any(|allowed| name.eq_ignore_ascii_case(allowed))
294:         {
295:             return Err(RuntimeError::new(
296:                 RuntimeErrorCode::InvalidRequest,
297:                 format!("Windows runtime context returned non-allowlisted variable {name}"),
298:                 Some("windows.runtimeContext.environment"),
299:                 false,
300:             ));
301:         }
302:     }
303:     Ok(())
304: }
