306: pub(crate) fn merge_windows_environment(
307:     baseline: &BTreeMap<String, String>,
308:     overlay: &BTreeMap<String, String>,
309: ) -> RuntimeResult<BTreeMap<String, String>> {
310:     let mut seen = Vec::<String>::new();
311:     for name in overlay.keys() {
312:         if name.is_empty() || name.contains('=') || name.contains('\0') {
313:             return Err(RuntimeError::invalid(
314:                 "invalid Windows environment variable name",
315:                 "execution.env",
316:             ));
317:         }
318:         if seen
319:             .iter()
320:             .any(|existing| existing.eq_ignore_ascii_case(name))
321:         {
322:             return Err(RuntimeError::invalid(
323:                 "Windows environment variable names must be unique case-insensitively",
324:                 "execution.env",
325:             ));
326:         }
327:         seen.push(name.clone());
328:     }
329:     let mut result = baseline.clone();
330:     for (name, value) in overlay {
331:         if let Some(existing) = result
332:             .keys()
333:             .find(|existing| existing.eq_ignore_ascii_case(name))
334:             .cloned()
335:         {
336:             result.remove(&existing);
337:         }
338:         result.insert(name.clone(), value.clone());
339:     }
340:     Ok(result)
341: }
